-- Xodim boti PR-12: Orbit (zqpglkxbtpkvyraxquao) dagi eski ma'lumotni Hanguk'ga ko'chirish.
-- 101 ta kunlik hisobot (25.07–02.11) va Hanguk'da yo'q 18 ta vazifa (hammasi Asrbek'niki).
-- Takror ishga tushirilsa hech narsa ikki marta yozilmaydi (on conflict do nothing).
-- Ma'lumot Orbit'dan olingan; tekshiruv: md5 = cc91ebd51d273a0922992e6123f7a113.

alter table public.daily_reports drop constraint if exists daily_reports_source_check;
alter table public.daily_reports add constraint daily_reports_source_check
  check (source in ('telegram', 'crm', 'orbit'));

insert into public.daily_reports (user_id, report_date, raw_text, done, blockers, plan, ai_parsed, source, created_at, updated_at)
select (x->>'u')::uuid, (x->>'dt')::date, x->>'r', x->>'d', x->>'b', x->>'p',
       (x->>'d') is not null or (x->>'b') is not null or (x->>'p') is not null,
       'orbit', (x->>'c')::timestamptz, (x->>'m')::timestamptz
from jsonb_array_elements($orbit$[{"b": null, "c": "2026-07-25T09:07:07.337193+00:00", "d": "Ishxonaga kelib, 7 ta notariusga hujjat topshirildi. 2 ta o'quvchining hujjatlari tarjima qilinib pochta qilindi.", "m": "2026-07-26T15:10:59.655017+00:00", "p": "Qolgan o'quvchilarning hujjatlarini tarjima qilib pochta qilish. Notariusdan o'z hujjatlarini olib kelish.", "r": "Bugun ertalab ishxonaga kelib, yettita notariusga hujjat topshirdim va keyin ikkita o'quvchining hujjatlarini tarjima qilib, ularni pochta qildim. Ertaga rejalarim yana qolgan o'quvchilarni tarjima qilib pochta qilish va notariusdan hujjatlarimni olib kelish.", "u": "7866551c-6c3d-4ea8-8185-78a8e63bd6d3", "dt": "2026-07-25"}, {"b": "Zamera VIP uchun yangi VIP shartnoma qilinganligi sababli shartnoma hali to'ldirib berilmadi", "c": "2026-07-27T13:06:51.517877+00:00", "d": null, "m": "2026-07-27T13:23:06.123+00:00", "p": "Ertaga viza uchun bitta o'quvchi keladi; chorshanba kuni viza uchun yana bitta o'quvchi keladi (eslatib yozib qo'yiladi); Zamera VIPdan yangi shartnomani so'rash kerak; Gemyungdan qolgan ikkita qizga telefon qilib, shartnomani qaytadan to'ldirib berishlarini so'rash kerak", "r": "Ertaga viza uchun bitta o'quvchi keladi, keyin chorshanba kuni viza uchun yana bitta o'quvchi keladi, u o'quvchiga eslatib yozib qo'yaman. Keyin Zamera VIPga shartnomasini, ya'ni boshqa yangi VIP shartnoma qilinganligi uchun uni eslatib qo'yishim kerak, hali to'ldirib bermadi. Ertaga shuni so'rashim kerak, keyin ikkita qizimiz bor Gemyungdan qolgan, ana shu qizlarga ham telefon qilib shartnomani boshqadan to'ldirib berishligini aytishim kerak tashlab berganimizni.", "u": "0525a29d-32ce-4c3e-94b1-bddf42a776f9", "dt": "2026-07-27"}, {"b": null, "c": "2026-07-27T10:12:24.361911+00:00", "d": "Ertalab notariusga 15 ta hujjat olib borib tushlikda qaytarib oldi; 10 ta hujjatni notarius qildirib, o'sha 10 talabaning hujjatlarini tarjima qildi; Xalq ta'lim vazirligiga 5 ta hujjat topshirdi; MyGovga 8 ta hujjat kiritdi.", "m": "2026-07-27T12:56:57.294602+00:00", "p": "Ertaga 20 ta o'quvchining hujjatlarini tarjima qilish.", "r": "Bugun tushlik payti soat 12da notariusga borib 10 ta hujjatni notarius qilib keldim. Va tushlikdan keyin o'sha 10 ta talabani hujjatlarini olib kelib hammasini tarjima qildim.\n---\nBugun ertalab notariusga 15 ta hujjat olib bordim. Obedda hujjatlarni borib qaytarib olib keldim. Xalq ta'lim vazirligiga beshta hujjatni topshirdim. MyGovga sakkizta hujjatni kiritdim. Ertaga 20 ta o'quvchini hujjatlarini tarjima qilib chiqishim kerak.", "u": "7866551c-6c3d-4ea8-8185-78a8e63bd6d3", "dt": "2026-07-27"}, {"b": null, "c": "2026-07-28T17:21:15.752198+00:00", "d": "Everest tur firmasi bilan bog'lanib, vizaga kiritiladigan kafil hujjati haqida ma'lumot olindi. Vizasi ko'rinmayotgan o'quvchining ma'lumotlarini va tekshirish usulini so'radi. Soyung uchinchi raundga topshirayotgan o'quvchining barcha onlayn hujjatlarini yig'ib universitetga topshirdi, shuningdek Excel variantda ham ma'lumotlarni to'ldirib topshirdi. Bankshot qo'yilishi kerak bo'lgan o'quvchi (Anna) bilan gaplashib, uni bankshotga ertaga chaqirdi. Yozishmalarga javob berishga va hujjat tikishga yordam berdi.", "m": "2026-07-28T17:22:26.058+00:00", "p": "Shu oyda pochta orqali ketgan hujjatlarni kompyuterga, jadvalga kiritish kerak. Soyungga elektron vizali uchta o'quvchining hujjatlarini yig'ib berish kerak. Namseoulga elektron viza orqali topshirayotgan bitta o'quvchining kadastr hujjatlarini Muhsin aka aytgan ketma-ketlikda tashlab berish kerak.", "r": "Bugun qilgan vazifalarim Everest tur firmasi bilan bog'lanib, vizaga kiritiladigan kafl hujjati haqida ma'lumot oldim. Keyin vizasi ko'rinmayotgan o'quvchini ma'lumotlarini va qanaqa tekshirishni so'radim. Undan keyin Soyung uchinchi raundga topshirayotgan o'quvchini hamma onlayn hujjatlarini yig'ib universitetga topshirdim va undan tashqari Excel variantda ham ma'lumotlarni to'ldirib topshirib qo'ydim. Keyin bankshot qo'yilishi kerak bo'lgan o'quvchi bilan gaplashib Annani Soy Annani bankshotga chaqirdim ertaga. I orada yozganlarga javob berishga yordam berdim. Tikishga yordam berdim hujjatni. Bo'ldi. Ertaga qiladigan vazifalarim hozircha pochta ketgan hujjatlarni shu paytgacha ketgan shu oyda ketgan pochta hujjatlarini yozib olganman, uni kompyuterga kiritishim kerak jadvalga. Keyin Soyungga elektron vizali uchta o'quvchini hujjatlarini yig'ib tashlab berishim kerak.\n---\nErtaga qiladigan vazifalarimdan bittasini aytish esimdan chiqibdi boyagi goalsda. Namseoulga elektron viza orqali topshirayotgan bitta o'quvchini kadastr hujjatlarini qayta ketma-ketlikda Muhsin aka aytgan ketma-ketlikda tashlab berishim kerak Namseoul uchun.", "u": "26a28e7e-9052-4481-a5d3-f8f44c3d7725", "dt": "2026-07-28"}, {"b": null, "c": "2026-07-29T05:21:41.758155+00:00", "d": "10 ta o'quvchi bilan gaplashdi, 3 ta yangi lit qo'shdi, 4 ta o'quvchiga shartnoma qildirdi (2 ta premium, 2 ta standart tarif).", "m": "2026-07-29T05:21:41.637+00:00", "p": null, "r": "Bugun 10 ta o'quvchi bilan gaplashdim, yangi uchta lit qo'shdim, to'rtta o'quvchiga shartnoma qildirdim, ikkitasi premium shartnoma, ikkitasi standart tarif shartnomasi bo'ldi.", "u": "0525a29d-32ce-4c3e-94b1-bddf42a776f9", "dt": "2026-07-29"}, {"b": "Ba'zi o'quvchilar telefonni ko'tarmadi, ota-onalar bilan maslahatlashish kerakligi sababli javob kechikmoqda.", "c": "2026-08-04T13:03:16.896273+00:00", "d": "6-7 yangi o'quvchiga tariflarni tushuntirdi. Yangi litlar bilan telegram va telefon orqali ishladi, telefonni ko'tarmaganlarga Instagram va telegram orqali yozib chiqdi. Til kursiga qiziqish bildirganlarning nomerlarini Excel faylga yozib chiqdi va Hangukga lead qo'shdi.", "m": "2026-08-04T13:04:36.476+00:00", "p": "Ertaga bugungi gaplashgan litlarning javobini bilish, telefonni ko'tarmagan yangi litlarga qayta telefon qilish va qolgan leadlarni Hangukga qo'shish.", "r": "Assalomu alaykum. Bugun oltita yo yettita yangi o'quvchiga tariflarni tushuntirdim. Ertaga javobini aytishadi, chunki uydagilari bilan maslahatlashib ko'radi yoki ota-onasi qoldirgan o'g'li bilan maslahatlashib ko'radi. Ertaga javobimizni aytamiz deyishdi, keyin yangi litlar bilan ishladim, ya'ni o'sha telegram, telefon qilib chiqdim. Telefonimni ko'tarmaganlariga yozib chiqdim. Instagram, telegram orqali. Ertaga qiladigan ishlarim bugungi gaplashgan litlarimni javobini bilish. Keyin ko'tarmagan yangi litlar keyin qayta telefon qilib chiqish, keyin.\n---\nKeyin til kursiga qiziqish bildirayotganlarni ayt. Bitta Excel fayl ochib, nomerlarini yozib chiqdim. Hangukga lead qo'shdim keyin. Qolgan leadlarni ertaga qo'shaman.", "u": "0525a29d-32ce-4c3e-94b1-bddf42a776f9", "dt": "2026-08-04"}, {"b": null, "c": "2026-08-04T13:39:08.116442+00:00", "d": "Telegram orqali yozgan eski mijozlar (allaqachon shartnoma qilib bo'lgan o'quvchilar) bilan ishlandi, ularning savollariga javob berildi. Dumaloqcha qirqildi.", "m": "2026-08-04T13:39:14.208+00:00", "p": null, "r": "Bugun telegramdan yozgan eski mijozlar bilan ishladim, ya'ni biz bilan allaqachon shartnoma qilib bo'lgan o'quvchilarni savollariga javob berib turdim. Va dumaloqcha qirqdim.", "u": "26a28e7e-9052-4481-a5d3-f8f44c3d7725", "dt": "2026-08-04"}, {"b": null, "c": "2026-08-04T09:14:58.79607+00:00", "d": "10 ta hujjatni notariusga olib bordi, 20 ta hujjatni MyGov tizimiga kiritdi, shundan 15 tasiga to'lov qilindi (5 tasi to'lovsiz qoldi), 8 ta hujjatni tarjima qildi, yettita o'quvchi bilan gaplashdi", "m": "2026-08-04T09:15:09.578+00:00", "p": null, "r": "Bugun 10 ta hujjatni notariusga olib bordim, 20 ta hujjatni MyGovga kiritdim, 15 tasiga to'lov qilindi, beshtasi qoldi. 8 ta hujjatni tarjima qildim. Yettita o'quvchi bilan gaplashdim.", "u": "3c67ee12-ca41-4293-a266-a85de37218b7", "dt": "2026-08-04"}, {"b": null, "c": "2026-08-04T09:08:12.150168+00:00", "d": "10 ta hujjatni notariusga olib bordi, 8 ta hujjatni kiritdi va 15 ta hujjat tarjima qildi", "m": "2026-08-04T09:08:19.607+00:00", "p": "ertaga 15 ta hujjatni notariusga olib borish va 10 tasini tarjima qilish kerak", "r": "Men bugun 10 ta hujjat notariusga olib bordim. Sakkizta hujjatni menga kiritdim va 15 ta hujjat tarjima qildim. Ertaga 15 ta hujjat notariusga olib borishim kerak va 10 tasini tarjima qilishim kerak.", "u": "7866551c-6c3d-4ea8-8185-78a8e63bd6d3", "dt": "2026-08-04"}, {"b": null, "c": "2026-08-04T09:34:38.629897+00:00", "d": "Seoyeong universitetiga (Mukhtorov Ibrohimjon) uchun kontrakt qaytarib olish arizasi to'ldirildi. Barcha emaillar tekshirilib, kamchiliklar bartaraf qilindi.", "m": "2026-08-04T09:34:44.176+00:00", "p": null, "r": "Bugun Seoyeong universitetiga (Mukhtorov Ibrohimjon) uchun kontrakt qaytarib olish arizasini to'ldirdim. Barcha emaillarni tekshirib, kamchiliklarni bartaraf qildim.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-08-04"}, {"b": "Ba'zi lidlar telefonni ko'tarmadi.", "c": "2026-08-05T14:44:42.634202+00:00", "d": "Instagramda yangi lidlar bilan gaplashib, tariflarni tushuntirdim va Telegram orqali tariflarni tashlab qo'ydim. Kechagi lidlarga telefon qildim, ko'tarmaganlarga Telegram va Instagram orqali yozib qo'ydim. Hamma lidlarni Hangukga qo'shib qo'ydim.", "m": "2026-08-05T14:44:48.766+00:00", "p": "Ertaga bugun ko'tarmagan lidlar bilan ishlayman, agar yangi lidlar bo'lsa ular bilan ham ishlayman.", "r": "Assalomu alaykum. Bugun yana Instagramda yengilliklar bilan gaplashdim va tariflarni tushuntirib, Telegram orqali bog'lanib tariflarni tashlab qo'ydim. Keyin kechagi gaplashgan liklarimga ham telefon qildim. Ular rostdan ko'tarmaganlari bo'ldi. Ularga ham Telegram orqali yozib qo'ydim. Keyin ko'tarmaganlarga ham Instagram orqali yozib qo'ydim hammasiga bog'lanish uchun. Ertaga borib yana bugun ko'tarmaganlar bilan ishlayman. Keyin agarda yengilliklar bo'lsa, ular bilan ham ishlayman. Keyin hamma liklarni Hangukga qo'shib qo'ydim. liklar bo'yicha", "u": "0525a29d-32ce-4c3e-94b1-bddf42a776f9", "dt": "2026-08-05"}, {"b": "Elektron viza (bankshot qo'ydirish) masalasida muammo paydo bo'ldi.", "c": "2026-08-05T13:15:19.028853+00:00", "d": "Telegram orqali shartnoma qilgan eski o'quvchilarning savollariga javob berib, ular bilan ishlandi. Hanguk saytiga litlarni qo'shishda Ominaga yordam berildi.", "m": "2026-08-05T13:15:25.686+00:00", "p": "Ertaga elektron viza/bankshot masalasi ustida ishlanadi.", "r": "Bugun Telegramdan yozgan eski o'quvchilari, ya'ni biz bilan shartnoma qilib bo'lgan o'quvchilarni savollariga javob berib, ular bilan ishladim. va litlarni qo'shish uchun Hanguk saytiga litlarni qo'shish uchun Ominaga yordam berdim. Muammo elektron viza so'yung masalasida muammo paydo bo'ldi, bankshot qo'ydirish masalasida. Bu masala bo'yicha ertaga ishlaniladigan bo'ldi va bu ertangi vazifam.", "u": "26a28e7e-9052-4481-a5d3-f8f44c3d7725", "dt": "2026-08-05"}, {"b": null, "c": "2026-08-05T08:09:58.735414+00:00", "d": "10 ta hujjatni notariusga olib bordi va 10 ta hujjatni tarjima qildi. Bitta o'quvchining barcha hujjatlarini tayyorlab qo'ydi. Sakkizta hujjatni tarjima qilib, tikib, pechatlatib, imzolatdi.", "m": "2026-08-05T13:11:05.177+00:00", "p": "Bitta o'quvchining hujjatlarini ertaga vizaga jo'natish rejalashtirilgan.", "r": "Men bugun 10 ta hujjat notariusga olib bordim va 10 ta hujjat tarjima qildim.\n---\nMen bugun obedda soat 1da ishga keldim. Keyin bitta o'quvchimizni hamma hujjatlarini tayyorlab ertaga vizaga jo'natishga tayyorlab qo'ydim. Undan tashqari sakkizta hujjatni tarjima qilib chiqarib tikib pechatlab, pechatlatib imzolattdim.", "u": "7866551c-6c3d-4ea8-8185-78a8e63bd6d3", "dt": "2026-08-05"}, {"b": "Printer yaxshi ishlamayapti, xira chiqarayapti, shu sababli bugun Soyongga arizani tashlab bo'lmadi.", "c": "2026-08-05T13:21:41.941003+00:00", "d": "Emaillarga javob berildi va emaillar tekshirildi, Soyong elektron vizalari bo'yicha ish olib borildi, dumaloqcha kesildi va beshta universitetda admission guideline qidirildi.", "m": "2026-08-05T13:21:50.032+00:00", "p": "University of Seoul bilan bog'lanish, Soyong bilan 36 yoshli yangi o'quvchi haqida gaplashish, Soyong universitetiga kontrakt qaytarib olish arizasini jo'natish va Tongyongdan sertifikat admission so'rash kerak.", "r": "Bugun emaillardan javob berdim, emaillarni tekshirdim, Soyong elektron vizalari bo'yicha ishladim, dumaloqcha kesdim va beshta universitetda admission guidelineni qidirdim. Ertaga qilishim kerak bo'lgan ishlar University of Seoul bilan bog'lanish, Soyong bilan gaplashish, 36 yoshli yangi o'quvchi haqida, yana Soyong universitetiga kontrakt qaytarib olish arizasini jo'natish va Tongyongdan sertifikat admission so'rashim kerak. Muammo printerimiz yaxshi ishlamayapti, xira chiqarayotgani uchun bugun Soyongga arizani tashlay olmadim.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-08-05"}, {"b": "Telefon qilinganlarning ko'pchiligi ko'tarmadi. Telegramda ko'pchiligi xabarni o'qib javob yozmadi.", "c": "2026-08-06T13:29:53.728971+00:00", "d": "Bugun yangi tushgan litlarga telefon qilib chiqildi va Telegram orqali tariflar tashlab qo'yildi. Kechagi tariflarni tushuntirilgan litlarga ham telefon qilib chiqildi, Telegramdan yozildi.", "m": "2026-08-06T13:30:08.108+00:00", "p": "Ertaga bugun tariflar tashlangan litlar javob berishi kutiladi. Bugun gaplashilganlar bilan ertaga yana gaplashiladi. Olmos aka yoqgan reklamadan tushgan litlar bilan gaplashiladi.", "r": "Assalomu alaykum. bugun ham yangi litlar tushgan ekan, o'shalarga telefon qilib chiqib, Telegram orqali tariflarni tashlab qo'ydim. ular bugun ota-onalari bilan maslahatlashib ko'rib, ertaga javobini aytarkan. keyin kechagi telefon qilib, tariflarni tushuntirganlarimga telefon qilib chiqdim. ularni ko'pchiligi ko'tarmadi. Telegramdan yozdim, Telegramdan o'qib turib yozishmadi yokida o'qiganlari javob yozdi, lekin ko'pchiligi yozmadi. ertaga ham yana bugun gaplashganlarim bilan gaplashaman, keyin boya Olmos aka reklama yoqdim deb aytdilar. o'sha reklamadan tushgan litlar bilan gaplashaman.", "u": "0525a29d-32ce-4c3e-94b1-bddf42a776f9", "dt": "2026-08-06"}, {"b": "Gwangju universiteti e-visada o'quvchidan yillik daromad talab qilmoqda.", "c": "2026-08-06T13:35:44.836556+00:00", "d": "Telegramdan o'quvchilarning savollariga javob berildi. Gwangjuga topshirgan o'quvchining e-visa uchun talabnomasi bilan tanishib chiqildi va o'quvchi ogohlantirildi.", "m": "2026-08-06T13:35:52.455+00:00", "p": "Ertaga bu masalani o'quvchiga tushuntirib, shu bo'yicha ishlash kerak.", "r": "Bugun telegramdan yozgan o’quvchilarning savollariga javob berdim. Gwangjuga topshirgan o’quvchining e visa uchun talabnimasi bilan tanishib o’quvchini ham ogohlantirdim.\n\nMuammo : Gwangju universiteti e visada oquvchidan yillik daromad talab qilayabti ertangi vazifam shuni o’quvchiga tushuntirib shu bo’yivha ishlash kerak", "u": "26a28e7e-9052-4481-a5d3-f8f44c3d7725", "dt": "2026-08-06"}, {"b": null, "c": "2026-08-06T12:07:41.076839+00:00", "d": "Emaillarni tekshirib javob berildi. Soyong universitetidan yangi talabalar uchun talablar tayyorlab berildi. Soyong universitetiga kontrakt qaytarib olish arizasi to'ldirib berildi. 20ta universitetning saytiga kirib Admission guidelinelari tekshirildi.", "m": "2026-08-06T12:07:48.683+00:00", "p": "Certificate admissionni tekshirish va qolgan universitetlarning saytlarini tekshirish kerak.", "r": "Bugun: emaillarni tekshirib javob berdim. Soyong universitetidan yangi talabalar uchun talablarni dorab berdim va Soyong universitetiga kontrakt qaytarib olish arizasini toldirib tashlab berdim 20ta universitetning saytiga kirib Admission guidelinelarini. \n\nErtaga: certificate admissionni tekshirish, va qolgan universitetlarni saytlarini tekshirishim kerak. \n\nMuammo yo'q.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-08-06"}, {"b": "Mammo Telegramga kontakt qo'sha olmadi. Nojisk shartnomasini to'g'irlattirish qoldi.", "c": "2026-08-07T17:00:00.582144+00:00", "d": "Telegram, telefon, Instagram javoblar: 1) Xabarlarga javob berdi; 2) Kommentlarga like bosdi; 3) Olmas aka bilan dialog tuzdik va o'quvchilarga telefon qildi; 4) Kechagi gaplashganlarimiz bilan qayta gaplashdi; 5) Ko'tarmaganlarga aloqa qildi; 6) Ko'targanlari bilan gaplashdi.", "m": "2026-08-07T17:01:14.617+00:00", "p": "Ertaga: Telegram va Instagramga javob berish; telefon qo'ng'iroqlarga javob berish; ko'tarmaganlarni qayta ishlamoq; bugungi va kechagi litlar bilan davom etish.", "r": "Assalomu alaykum, yaxshimisiz? bugun Telegram, telefonlarga javob berdim, Instagramlarga, komment yozganlarga yoki lichkaga yozganlarga javob berib chiqdim. kommentlarga like bosib chiqdim. Keyin Olmas aka bilan dialog tuzdik, shu dialog bo'yicha o'quvchilarga telefon qilib chiqdim. Kechagi gaplashganlarim bilan gaplashib chiqdim yana qayta. Keyin ko'tarmaganlarga yana qayta aloqa qildim. ko'targanlari bilan gaplashdim, ko'tarmaganlari bilan ertaga gaplashaman. Mammo Telegramga kontakt qo'shib bo'lmayapti.\n---\nKeyin yana bitta muammo bor, Nojisk shartnomasini to'g'irlattirib berishingiz kerak edi. Shu qoldi. Ertaga qiladigan ishlarim: Telegram, Instagramlarga yana javob beraman yozganlarga. Telefon bo'lsa, telefonlarga javob beraman, chunki telefon orqali ham o'sha o'quvchilar telefon qilyapti. Ko'tarmaganlariga yozib qo'yganlarim, keyin yana o'sha bugungi, kechagi litlar bilan ishlayman.", "u": "0525a29d-32ce-4c3e-94b1-bddf42a776f9", "dt": "2026-08-07"}, {"b": null, "c": "2026-08-07T14:45:03.251905+00:00", "d": "Telegram orqali biz bilan allaqachon shartnoma qilib bo'lgan eski o'quvchilarning savollariga javob berildi.", "m": "2026-08-07T14:45:09.789+00:00", "p": "Viza jarayoni uchun tayyorlanayotgan o'quvchilarning holatini tekshirib chiqish: guruhda bormi, hujjatlarni hammasini tashlayaptimi, yangiliklardan xabardormi.", "r": "Bugun Telegramdan yozgan, biz bilan allaqachon shartnoma qilib bo'lgan eski o'quvchilarni savollariga javob berdim. Muammo bo'lmadi. Ertangi qiladigan vazifam viza jarayoni uchun tayyorlanayotgan o'quvchilarni holatini tekshirib chiqish, ya'ni guruhda bormi, hujjatlarni hammasini tashlayaptimi, yangiliklardan xabardormi.", "u": "26a28e7e-9052-4481-a5d3-f8f44c3d7725", "dt": "2026-08-07"}, {"b": null, "c": "2026-08-07T12:31:08.894453+00:00", "d": "Bugun bitta o'quvchining hamma hujjatlarini tarjima qilib, imzolatib, pechatlatib tayyorlab qo'ydi, chunki u keyingi hafta vizaga ketadi.", "m": "2026-08-07T12:31:17.928+00:00", "p": "Ertaga yana bitta o'quvchi keladi, uning ham hujjatlarini tayyorlab qo'yadi, chunki u ham keyingi hafta elchixonaga vizaga ketadi.", "r": "bugun bitta o'quvchi bizning hamma hujjatlarini tarjima qilib, imzolati pechatlatib tayyorlab qo'ydim, chunki keyingi hafta viza vizaga ketadi, shu uchun ertaga ham yana bitta o'quvchimiz bor, keyingi hafta ketadigan vizaga elchixonaga ertaga kelib uni hujjatini ham tayyorlab qo'yaman.", "u": "7866551c-6c3d-4ea8-8185-78a8e63bd6d3", "dt": "2026-08-07"}, {"b": "Bugun hech qanaqa muammo bo'lmadi.", "c": "2026-08-07T14:05:46.714203+00:00", "d": "Bugun emaillarni tekshirdim va ularga javob berdim. Soyong universitetiga kontrakt qaytarib olish arizasini qayta to'ldirib topshirdim. Hanguk saytidagi ma'lumotlarni hammasini tasdiqladim.", "m": "2026-08-07T14:05:53.769+00:00", "p": "Ertaga Bavs universiteti bilan bog'lanib, bir o'quvchining student IDsini olib berish kerak va universitet admission guidelinelarini qidirib topish kerak.", "r": "Bugun emaillarni tekshirdim, emaillarga javob berdim. Soyong universitetiga kontrakt qaytarib olish arizasini qayta to'ldirib tashlab berdim. Hanguk saytidagi ma'lumotlarni tasdiqladim hammasini. Bugun hech qanaqa muammo bo'lmadi. Ertaga qiladigan ishim Bavs universiteti bilan bog'lanib, bir o'quvchini student IDsini olib berishim kerak va universitet admission guidelinelarini qidirib topishim kerak.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-08-07"}, {"b": "Kechagi telefon qilgan ba'zi o'quvchilar bugun javob bermadi. O'quvchilar GKS uchun alohida tarif yo'qligi haqida so'roq qo'yayotdi va GKS uchun alohida tarif yaratish mumkinmi degan savol ko'p kelib tushyapti.", "c": "2026-08-08T13:16:04.228305+00:00", "d": "Telegram va Instagram orqali 4 ta xabar javob berildi. Oldingi kechagi muammolar bo'yicha telefon qilindi. Til sertifikati yo'qlari bilan to'g'ridan-to'g'ri, sertifikati borlari bilan Olmos aka orqali 3-4 ta o'quvchi bilan gaplashildi. Telefon qilgan o'quvchilarga Telegram orqali javob yozildi va savollariga otvet berildi.", "m": "2026-08-08T13:17:45.808+00:00", "p": "Dushanba kuni javob bermaganlarni yana telefon qilish. Keyingi haftaga kelib o'quvchilar ofisga kelishsa, ularga ko'rsatib beriladi va batafsil ma'lumot beriladi. GKS uchun alohida tarif qilish bo'lakka savol ko'tarish.", "r": "Assalomu alaykum. Bugun Telegram Instagramga javob berdim. Keyin oldingi kechagi ko'tarmaganliklarga telefon qilib chiqdim, gaplashdim. Til sertifikati yo'qlari bilan asosan, til sertifikati borlari bilan Olmos aka gaplashdilar uchta to'rttasi bilan. Olmos aka tushuntirdilar. Keyingi haftaga kelmoqchi bo'lgan o'quvchilar bor, ofisga kelib ko'rib, keyin batafsil ma'lumot olib qolamiz dedi. Kechagi telefon qilganlarimga telefon qilsam bugun ko'tarmadi, Telegram orqali yozdim. Javob berganiga javob yozdim, savollariga otvet. Javob bermaganiga dushanba kuni qayt yana telefon qilib ko'raman.\n---\nMuammo bo'lyapti va o'quvchilardan taklif tushyapti. Reklamada GKSga topshirib beriladi, uchta shartnomadan bittasidan deyilgan. O'quvchilar tekinga topshirib berarkan deb telefon qilyapti. Ularga tushuntiryapmiz, uchta tarifdan bittasida qilsangiz tekinga topshirib beriladi. Ikkita o'zingiz tanlayotgan universitetda bittasi, shunda umumiy hisobda uchta universitetga topshirib beriladi sizniki deb. O'quvchilarga tushuntiryapmiz, lekin ular GKS uchun alohida tarif yo'qmi deb so'rashyapti. O'shaning uchun GKS uchun alohida tarif qilsak bo'ladimi deb so'ramoqchi edim.", "u": "0525a29d-32ce-4c3e-94b1-bddf42a776f9", "dt": "2026-08-08"}, {"b": null, "c": "2026-08-08T14:32:18.168156+00:00", "d": "Visaga kiradigan o'quvchilarning holati tekshirib chiqildi, muammo aniqlanmadi", "m": "2026-08-08T14:32:24.59+00:00", "p": "Dushanba kuni VIP tarifidagi Samandarning 1 kunlik bankshot masalasini hal qilish kerak", "r": "Visaga kiradigan o’quvchilat holatini tekshirib chiqdim\nMuammo yo’q\nDushanba kuni vip tarifidagi Samandarni 1 kunlik bankshot masalasini hal qilish kerak", "u": "26a28e7e-9052-4481-a5d3-f8f44c3d7725", "dt": "2026-08-08"}, {"b": null, "c": "2026-08-08T13:13:28.818475+00:00", "d": "Chala qolgan viza hujjatlarini o'rganib chiqdi", "m": "2026-08-08T13:13:33.428+00:00", "p": null, "r": "Chala qolgan viza hujjatlarini o'rganib chiqdim.", "u": "3c67ee12-ca41-4293-a266-a85de37218b7", "dt": "2026-08-08"}, {"b": null, "c": "2026-08-08T13:01:30.509426+00:00", "d": "Bitta o'quvchining barcha hujjatlarini tayyorlab, viza jarayoniga tayyorladi. Hujjatlarini tarjima qilib, printerdan chiqarib, tikib, tayyor qilib qo'ydi.", "m": "2026-08-08T13:01:34.647+00:00", "p": null, "r": "Bugun bitta oʻquvchimizni hamma hujjatlarini tayyorlab viza jarayonlariga tayyorlab qoydim hujjatlarini tarjima qilib printerdan chiqarib tikib tayyor qilib qoydim", "u": "7866551c-6c3d-4ea8-8185-78a8e63bd6d3", "dt": "2026-08-08"}, {"b": null, "c": "2026-08-08T14:04:38.754021+00:00", "d": "Emaillarni tekshirib, ularga javob berildi. Hanguk saytidan ma'lumotlar tasdiqlandi va 25 ta universitet saytidan admission guidelinelar ko'rib chiqildi.", "m": "2026-08-08T14:04:44.018+00:00", "p": "Dushanba kuni ikkita o'quvchining sertifikat admissionini so'rash va qolgan admission guidelinelarni qidirib ko'rish.", "r": "Bugun emaillarni tekshirib, emaillarga javob berdim. Hanguk saytidan ma'lumotlarni tasdiqladim va 25 ta universitetda saytidan admission guidelinelarni ko'rib chiqdim. Dushanba kuni ikkita o'quvchini sertifikat admissionini so'rab berishim kerak va qolgan admission guidelinelarni qidirib ko'rishim kerak. Hech qanaqa muammo yo'q bo'lmadi.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-08-08"}, {"b": null, "c": "2026-08-14T15:26:16.772372+00:00", "d": "E-maillarni tekshirib, ularga javob berildi. Hanguk saytidagi ma'lumotlar tasdiqlandi. Universitet ma'lumotlari sayt orqali qidirildi.", "m": "2026-08-14T15:26:22.789+00:00", "p": "Ertaga Hanguk saytidan yana ma'lumotlarni tasdiqlash va universitet ma'lumotlarini qidirish rejalashtirilgan.", "r": "Bugun e-maillarni tekshirib, e-maillarga javob berdim. Hanguk saytidagi ma'lumotlarni tasdiqladim. Universitet ma'lumotlarini qidirdim saytidan. Hech qanaqa muammo bo'lgani yo'q. Ertaga qiladigan ishim Hanguk saytidan yana ma'lumotlarni tasdiqlash va universitet ma'lumotlarini qidirish.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-08-14"}, {"b": "Sertifikati bor o'quvchilar telefon qo'ng'irog'iga javob berishmadi.", "c": "2026-08-17T15:16:19.688258+00:00", "d": "Telegram va Instagram xabarlariga javob berildi. Targetdagi sertifikati yo'q o'quvchilar til kursi examiga qo'shib chiqildi. Sertifikati bor 2-3 ta o'quvchiga telefon qilindi (ko'tarishmadi) va Telegram orqali bog'lanildi. Bitta o'quvchi bilan shartnoma qilindi. Viza uchun ketadigan o'quvchilarning kerakli hujjatlari ro'yxati tashlanib, ularning hujjatlari qaytadan yig'ildi va tarjimaga topshirildi.", "m": "2026-08-17T15:16:27.808+00:00", "p": "Telegram va Instagram xabarlariga javob beriladi, telefonlarga javob beriladi. Bugun telefonni ko'tarmagan o'quvchilarga qayta telefon qilinadi. Tarjimaga topshirilgan hujjatlarni olishga kelganlarning hujjatlari topshiriladi.", "r": "Assalomu alaykum, bugun Telegram Instagramga javob berdim, keyin target yoqilgan ekan va u yerdagi o'quvchilarni asosiy qismida sertifikat yo'q ekan. Ularni til kursi deb ochgan examga qo'shib chiqdim hammasini. Keyin sertifikati bor o'quvchilar bor ekan, ikkitami uchta, o'shalarga telefon qildim, ko'tarmadi. Telegram orqali bog'landim. Ertaga ham shu Telegram Instagramga javob berib, telefonlarga javob beraman, keyin o'sha bugungi telefonni ko'tarmagan o'quvchilarga telefon qilaman. Keyin bugun shu bitta o'quvchi shartnoma qildi, u kerakli hujjatlari ro'yxatini tashlab, visaga kirib ketadigan o'quvchilarimiz bor edi, o'shalardan ham hujjatlarni yig'ib tarjimaga topshirdim yana qayta. Ertaga keladi hujjatlarini olgani.", "u": "0525a29d-32ce-4c3e-94b1-bddf42a776f9", "dt": "2026-08-17"}, {"b": null, "c": "2026-08-17T13:01:20.285566+00:00", "d": "Ikkita oʻquvchining hujjatlari viza uchun elchixonaga tayyorlandi", "m": "2026-08-17T13:01:27.323+00:00", "p": "Ertaga oʻquvchilar kelib hujjatlarni olib ketishadi va ertaga ham shu reja davom etadi", "r": "Bugun ikkita oʻquvchini hujjatlarini viza uchun elchixonaga tayyorladim ertaga kelib olib ketisharkan ertaga ham shu reja", "u": "7866551c-6c3d-4ea8-8185-78a8e63bd6d3", "dt": "2026-08-17"}, {"b": null, "c": "2026-08-17T13:16:26.56052+00:00", "d": "Emaillarni tekshirdi va javob berdi. Bavsdagi bir talabaning student ID'sini so'rab berdi. Hanguk saytidan universitet ma'lumotlarini tasdiqladi.", "m": "2026-08-17T13:16:32.4+00:00", "p": "Qolgan universitet ma'lumotlarini tasdiqlash va admission guideline qidirish.", "r": "Bugun emaillarni tekshirdim, emaillarga javob berdim. Bavsdagi bir talabani student ID sini so'rab berdim. Hanguk saytidan universitet ma'lumotlarini tasdiqladim. Hech qanaqa muammo yo'q. Ertaga qiladigan ishim qolgan universitet ma'lumotlarini tasdiqlash va admission guideline qidirish.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-08-17"}, {"b": null, "c": "2026-08-18T18:02:54.761981+00:00", "d": "Telegram xabarlariga javob berildi va eski lidlarga yozildi. 5 nafar o'quvchining viza uchun hujjatlari ko'rib chiqildi: qaysi hujjatlar borligi va yo'qligi aniqlandi, ota-onalarning daromadlari, bank shot summalari va kassa zayavka raqamlari berib chiqildi.", "m": "2026-08-18T18:03:05.922+00:00", "p": "Ertaga elchixonaga hujjat topshirish uchun keladigan 5 nafar o'quvchini kutib olib, elchixonaga kuzatib yuborish. Shundan so'ng lidlar bilan ishlashni davom ettirish va Telegram xabarlariga javob berish.", "r": "Assalomu alaykum. Bugun Telegram telefonimga javob berdim. Asosan beshta o'quvchi keladi ertaga. O'shalarni viza uchun hujjatlarini ko'rib chiqdim. Qaysi hujjatlari bor, qaysi hujjatlari yo'q, ota-onaning daromadlari, qo'yiladigan bank shot summalari, kassa zayavka nomerlarini berib chiqdim. O'shalar bilan asosan ishladim bugun. Keyin eski litlarga ham yozdim Telegram orqali. Ertaga beshta o'quvchi keladi, Elchixonaga hujjat topshirish uchun, ularni kutib, Elchixonaga kuzatib yuborgandan keyin yana litlar bilan ishlayman, yechish Telegram telefonlarga javob beraman.", "u": "0525a29d-32ce-4c3e-94b1-bddf42a776f9", "dt": "2026-08-18"}, {"b": "Hech qanday muammo bo'lmadi.", "c": "2026-08-18T16:49:30.181808+00:00", "d": "Chungang universiteti sertifikat admission olish uchun forum to'ldirildi. Barcha emaillarga javob yozildi. Hanguk saytidan universitet ma'lumotlari tasdiqlandi.", "m": "2026-08-18T16:49:36.037+00:00", "p": "Ertaga Hanguk saytidan qolgan ma'lumotlarni tasdiqlash.", "r": "Bugun Chungang universiteti sertifikat admission olish uchun forum to'ldirib berdim. Emaillarga hammasiga javob yozdim va Hanguk saytidan universitet ma'lumotlarini tasdiqladim, hech qanday muammo bo'lgani yo'q. Ertaga qiladigan ishim Hanguk saytidan qolgan ma'lumotlarni tasdiqlash.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-08-18"}, {"b": null, "c": "2026-08-19T15:43:56.153806+00:00", "d": "Telegramda xabarlarga javob berildi. Viza uchun kelgan o'quvchilar bilan ishlandi (ularning barchasi bir vaqtda va ishdan keyin kelganligi sababli asosiy vaqt shularga sarflandi). Shuningdek, bank karta va sim karta uchun kelgan o'quvchilar qabul qilindi.", "m": "2026-08-19T15:44:53.229+00:00", "p": "Ertaga Telegram va Instagramdagi xabarlarga javob berish rejalashtirilgan.", "r": "Assalomu alaykum, bugun Telegram telefonlarga javob berdim. Viza uchun o'quvchilar keldi. Keyin bank karta sim karta uchun o'quvchilar keldi. Bugun asosan viza uchun kelgan o'quvchilar bilan ishlandi. Chunki hammasi bitta payt keldi, yarim bir xillar rabotdan keyin keldi. O'shalar bilan ishlandi asosan. Ertaga yana shu Telegram Instagramlarga javob beraman.", "u": "0525a29d-32ce-4c3e-94b1-bddf42a776f9", "dt": "2026-08-19"}, {"b": null, "c": "2026-08-19T13:14:50.244177+00:00", "d": "Bugun 4 ta oʻquvchining hujjatini viza uchun elchixonaga tayyorlab berib yuborildi, bitta diplom apostili pechatlatib kelindi va Boyotaga pochta berib yuborildi.", "m": "2026-08-19T13:14:56.442+00:00", "p": "Ertaga elchixonaga hujjat olib boriladi.", "r": "Bugun 4 ta oʻquvchini hujjatini viza uchun elchixonaga tayyorlab berib yubordim bitta diplom apostilini pechatlatib keldm boyotaga pochta berib yubordim ertaga elchixonafa hujjat olib boraman", "u": "7866551c-6c3d-4ea8-8185-78a8e63bd6d3", "dt": "2026-08-19"}, {"b": null, "c": "2026-08-20T12:02:00.324619+00:00", "d": "Telefonlar va telegramga javob berildi. Kechagi vizaga kirgan o'quvchilarning qolgan hujjatlari bilan ishlandi. Ofisga kelgan vizaga hujjatlari chala qolgan bitta o'quvchi bilan ishlandi. Bitta yangi o'quvchi standart tarifiga to'lov qildi va unga kerakli hujjatlar ro'yxati tashlandi. Eski lidlar bilan ishlandi.", "m": "2026-08-20T12:02:09.701+00:00", "p": "Ertaga telegram va instagramga javob beriladi, lidlar bilan ishlanadi.", "r": "Assalomu alaykum, bugun telefonlarga va telegramga javob berdim. Kechagi vizaga kirib ketgan o'quvchilarni qolgan hujjatlari bilan ishladim va bugun yana bitta o'quvchi keldi, vizaga hujjatlari qolib ketuvdi yarmi. Ya'ni chalasi bor ekan, o'shalari bo'yicha ofisga keldi, shular bilan ishladik. Endi bitta yangi o'quvchi standart tarifiga to'lov qildi. Unga kerakli hujjatlar ro'yxatini tashladim. Ertaga yana telegram, instagramga javob beraman va litlar bilan ishlayman. Bugun avvalgincha litlar bilan ishladim, eski litlar bilan. Ertaga ham litlar bilan ishlayman. Hech qanaqa muammo bo'lmadi.", "u": "0525a29d-32ce-4c3e-94b1-bddf42a776f9", "dt": "2026-0