7", "dt": "2026-10-03"}, {"b": null, "c": "2026-10-05T16:26:04.238007+00:00", "d": "Bugun universitet admission guidelinelarini yig'ib, Hanguk saytiga universitet ma'lumotlarini kiritdim. Ominaga so'ragan ma'lumotlarni berdim.", "m": "2026-10-05T16:26:10.457+00:00", "p": "Ertaga qiladigan ishim qolgan admission guidelinelarni olib, Hanguk saytini to'ldirish.", "r": "Bugun universitet admission guidelinelarini yig'ib, Hanguk saytiga universitet ma'lumotlarini kiritdim. Ominaga so'ragan ma'lumotlarni berdim. Hech qanaqa muammo bo'lgani yo'q. Ertaga qiladigan ishim qolgan admission guidelinelarni olib, Hanguk saytini to'ldirish.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-05"}, {"b": null, "c": "2026-10-06T14:19:51.871715+00:00", "d": "Universitet ma'lumotlarini, admission guidelinelarini qidirib topib, Hanguk saytiga joyladim.", "m": "2026-10-06T14:19:56.81+00:00", "p": "Qolgan ma'lumotlarni Hanguk saytiga joylash.", "r": "Bugun universitet ma'lumotlarini, admission guidelinelarini qidirib topib, Hanguk saytiga joyladim. Hech qanaqa muammo bo'lgani yo'q. Ertaga qiladigan ishim qolgan ma'lumotlarni Hanguk saytiga joylash.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-06"}, {"b": null, "c": "2026-10-07T13:22:34.650586+00:00", "d": "Bugun 365 ta Excel bo'yicha universitetlarning ma'lumotini topib, Hanguk saytiga joylashish tugatildi. Hanguk saytida yo'q universitetlar chiqarib tashlandi.", "m": "2026-10-07T13:22:40.043+00:00", "p": "Ertaga Ajou universitetiga GKS topshirish rejalashtirilgan.", "r": "Bugun 365 ta Excel bo'yicha universitetlarni hammasini ma'lumotini bir topib Hanguk saytiga joylashishni tugatdim. Hanguk saytidagi yo'q universitetlarni chiqarib tashlandi. Hech qanaqa muammo yo'q. Ertaga qiladigan ishim Ajou universitetiga GKS topshirishim.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-07"}, {"b": null, "c": "2026-10-08T15:36:28.724401+00:00", "d": "Omina so'ragan universitet ma'lumotlari bilan to'g'rima to'g'ri ishladi, ma'lumotlarni topib yuklab oldi.", "m": "2026-10-08T15:36:34.775+00:00", "p": "Ertaga universitet deadlinelarini tekshiradi va universitet tanlagan o'quvchilar ishi bilan shug'ullanadi.", "r": "Bugun Omina soragan universitet malumotlari bilan to'g'rima to'g'ri ishladim. Ma'lumotlarni topib yuklab oldim. Muammo yo'q. Ertega universitet deadlinelarini tekshiraman. Va universitet tanlagan o'quvchilar ishi bilan shugullanaman.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-08"}, {"b": null, "c": "2026-10-12T15:42:38.665685+00:00", "d": "Universitet guideline'dagi deadlinelarini tekshirib chiqdim va GKS ma'lumoti bo'yicha ishladim.", "m": "2026-10-12T15:42:48.756+00:00", "p": "Ertaga yana GKS bilan shugullanaman.", "r": "Bugun universitet guidelinedagi deadlinelarini tekshirib chiqdim. Va gks ma'lumoti bo'yicha ishladim. Muammo yo'q. Ertega yana gks bilan shugullanaman.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-12"}, {"b": null, "c": "2026-10-13T13:05:15.52364+00:00", "d": "Universitet tanlashda ma'lumotlar berib turildi, GKS ishlari aniqlashtirildi va Hanguk saytidagi ma'lumotsiz universitetlar ma'lumotlarini qidirish boshlandi.", "m": "2026-10-13T13:05:30.236+00:00", "p": "Qolgan universitet ma'lumotlarini ko'rib chiqish.", "r": "Bugun universitet tanlashda malumotlarni berib turdim, gks ishlsrini sniqlashgirdim va hanguk saytidagi malumotsin universitetlarni mdlumotlarini qidirishni boshladim. Muammo yoq. Ertega qolgan universitet malumotlarini kotib chiqaman.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-13"}, {"b": null, "c": "2026-10-14T18:06:26.727249+00:00", "d": "GKS ma'lumotlarini yig'ib chiqdim, GKS hujjatlarini tayyorladim. Qolgan universitet admission guidelinelarini Excel fayl qilib olib, o'sha Excel fayl bo'yicha qidirdim.", "m": "2026-10-14T18:06:32.927+00:00", "p": "Qolgan admission guidelinelarni qidirish.", "r": "Bugun GKS ma'lumotlarini yig'ib chiqdim, GKS hujjatlarini tayyorladim. va qolgan universitet admission guidelinelarini Excel fayl qilib olib, o'sha Excel fayl bo'yicha qidirdim. Hech qanaqa muammo yo'q. Ertaga qiladigan ishim qolgan admission guidelinelarni qidirish bo'ladi.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-14"}, {"b": null, "c": "2026-10-16T14:46:17.746369+00:00", "d": "Chekesga kerak bo'lgan ma'lumotlar bilan ishladim, admission guidelinelarni qidirib ko'rdim.", "m": "2026-10-16T14:46:17.35+00:00", "p": "Chekes topshirish.", "r": "Bugun chekesga kerak bo'lgan ma'lumotlar bilan ishladim, admission guidelinelarni qidirib ko'rdim. Shunaqa muammo bo'lgani yo'q. Erta qiladigan ishim chekes topshirish", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-16"}, {"b": null, "c": "2026-10-20T13:21:07.648889+00:00", "d": "GKS ma'lumotlari bilan ishladim. Kecha topshirgan Ajou universitetiga GKSning qolgan qismlarini to'ldirdim va bugun Keungpook universitetiga GKS offline formulani to'ldirdim.", "m": "2026-10-20T13:21:07.515+00:00", "p": "Ikkala o'quvchi bilan yana qolgan ishlar bo'yicha ishlab, onlayn hujjatlarini tayyorlash.", "r": "Bugun GKS ma'lumotlari bilan ishladim. Kecha topshirgan Ajou universitetiga GKSni qolganlarini to'ldirdim va bugun Keungpook universitetiga GKS offline formulani to'ldirdim. Ertaga qiladigan ishim ikkala o'quvchi bilan yana qolgan ishlar bo'yicha ishlab, onlayn hujjatlarini tayyorlash bo'ladi. Hech qanaqa muammo bo'lgani yo'q.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-20"}, {"b": null, "c": "2026-10-21T13:42:14.733216+00:00", "d": "Hanguk saytiga joylanmagan universitet ma'lumotlarini qidirib topib, saytga joyladim.", "m": "2026-10-21T13:42:14.618+00:00", "p": "Ikkita GKSchining study planlari kutilyapti, o'sha study planlarini hammasini joylab, pochtaga tayyor qilib qo'yish.", "r": "Bugun Hanguk saytiga joylanmagan universitet ma'lumotlarini qidirib topib, Hanguk saytiga joyladim. Hech qanaqa muammo bo'lgani yo'q. Ertaga qiladigan ishim ikkita GKSchining study planlari kutilyapti, o'sha study planlarini hammasini joylab, pochtaga tayyor qilib qo'yish.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-21"}, {"b": null, "c": "2026-10-22T13:02:40.07624+00:00", "d": "Hanguk saytidagi qolgan universitet ma'lumotlarini joyladim va Gemyong universitetiga application form to'ldirib, online ariza topshirdim.", "m": "2026-10-22T13:02:39.704+00:00", "p": "Duksuk universitetiga online ariza to'ldirib, application fee to'lash.", "r": "Bugun Hanguk saytidagi qolgan universitet ma'lumotlarini joyladim va Gemyong universitetiga application form to'ldirdim. Online ariza topshirdim. Hech qanaqa muammo bo'lgani yo'q. Ertaga qiladigan isim Duksuk universitetiga online ariza to'ldirib, application fee to'lash.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-22"}, {"b": null, "c": "2026-10-23T14:15:04.544846+00:00", "d": "Dukson universitetiga onlayn ariza topshirildi, Kim Yung va Dukson universitetiga application fee to'landi, qolgan o'quvchilarning universitet deadlinelari ko'rib chiqildi, study plan va personal statementlar tekshirildi.", "m": "2026-10-23T14:15:04.166+00:00", "p": "Ikkita GKSchining hujjatlarini tayyor holatga keltirish va universitetga jo'natish uchun tayyorlash.", "r": "Bugun Dukson universitetiga onlayn ariza topshirdim. Kim Yung va Dukson universitetiga application fee to'landi. Va qolgan o'quvchilarni universitetlarini deadlinelarni ko'rib chiqib, study plan va personal statementlarini tekshirib chiqdim. Hech qanaqa muammo bo'lgani yo'q. Ertaga qiladigan ishim ikkita GKSchini hujjatlarini tayyor holatga keltirish va universitetga jo'natish uchun tayyorlash.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-23"}, {"b": null, "c": "2026-10-26T13:11:37.043918+00:00", "d": "Ajou universiteti uchun GKS va Duksung universitetining offline hujjatlarini tayyorlab chiqarib yuborildi.", "m": "2026-10-26T13:11:36.565+00:00", "p": "Til kurslari bilan ishlash, Keimyung application formani tayyorlash, offline hujjatlarini tayyorlash va Kyungpook universitetiga GKSga topshirish.", "r": "Bugun Ajou universiteti uchun GKS va Duksung universitetini offline hujjatlarini tayyorlab chiqarib yubordim. Hech qanaqa muammo bo'lgani yo'q. Ertaga qiladigan ishim til kurslari bilan ishlash va Keimyung application formani tayyorlab, offline hujjatlarini tayyorlash va Kyungpook universitetiga GKSga topshirish.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-26"}, {"b": "Bugun hisobot (achot) yozilmadi", "c": "2026-10-27T13:02:01.195916+00:00", "d": null, "m": "2026-10-27T13:02:09.532+00:00", "p": null, "r": "bugun achot yozmadm", "u": "3c67ee12-ca41-4293-a266-a85de37218b7", "dt": "2026-10-27"}, {"b": null, "c": "2026-10-27T14:32:03.965937+00:00", "d": "Til kursining admission guidelinelarini yig'ib Hanguk saytiga joyladim. Kimyung universitetining offlayn hujjatlarini tayyorladim.", "m": "2026-10-27T14:32:03.849+00:00", "p": "Kunbok universiteti uchun GKS ga offlayn va onlayn hujjatlarini tayyorlash.", "r": "bugun til kursini admission guidelinelarini yig'ib Hanguk saytiga joyladim. Kimyung universitetini offlayn hujjatlarini tayyorladim, hech qanaqa muammo bo'lgani yo'q. Ertaga qiladigan ishim Kunbok universiteti uchun GKSga offlayn hujjatlarini va onlayn hujjatlarini tayyorlash.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-10-27"}, {"b": null, "c": "2026-11-02T18:07:21.187858+00:00", "d": "Kyungpook universitetiga GKS topshirildi. Offlayn va onlayn hujjatlari ketdi va email orqali universitetlarga xatlar jo'natildi.", "m": "2026-11-02T18:07:21.052+00:00", "p": "Tekukhani universitetiga topshiradigan o'quvchilarning application formini to'ldirish.", "r": "Bugun Kyungpook universitetiga GKS topshirdik. Offlayn va onlayn hujjatlari ketdi va email orqali universitetlarga xatlar jo'natildi. Hech qanaqa muammo bo'lgani yo'q ertaga qiladigan ishim Tekukhani universitetiga topshiradigan o'quvchilarning application formini to'ldirish.", "u": "edf68c8c-a7df-403c-abc3-2083cf95d717", "dt": "2026-11-02"}]$orbit$::jsonb) x
where exists (select 1 from auth.users u where u.id = (x->>'u')::uuid)
on conflict (user_id, report_date) do nothing;

-- Vazifalar: id Orbit'dagi bilan bir xil; Asrbek (owner) yaratgan va bajaruvchisi.
insert into public.tasks (id, title, description, priority, status, due_date, assigned_to, created_by, completed_at, created_at, source)
select (x->>'id')::uuid, left(x->>'t', 200), x->>'d',
       case when x->>'p' in ('urgent', 'high', 'normal', 'low') then x->>'p' else 'normal' end,
       case x->>'s' when 'open' then 'todo' when 'done' then 'completed' else x->>'s' end,
       (x->>'due')::timestamptz,
       '55cee049-db90-4a2d-a031-227b34b17533', '55cee049-db90-4a2d-a031-227b34b17533',
       case when x->>'s' = 'done' then (x->>'u')::timestamptz end,
